#!/usr/bin/env python3
import sys, os, json, re, unicodedata, urllib.request, urllib.error, ssl
from collections import OrderedDict

USAGE = """Transform JSON (from a file, URL, or stdin) into discrete assignments to make it greppable

Usage:
  gron [OPTIONS] [FILE|URL|-]

Options:
  -u, --ungron     Reverse the operation (turn assignments back into JSON)
  -v, --values     Print just the values of provided assignments
  -c, --colorize   Colorize output (default on tty)
  -m, --monochrome Monochrome (don't colorize output)
  -s, --stream     Treat each line of input as a separate JSON object
  -k, --insecure   Disable certificate validation
  -x, --proxy      Set proxy configuration
      --noproxy    Comma-separated list of hosts for which not to use a proxy, if one is specified.
  -j, --json       Represent gron data as JSON stream
      --no-sort    Don't sort output (faster)
      --version    Print version information

Exit Codes:
  0\tOK
  1\tFailed to open file
  2\tFailed to read input
  3\tFailed to form statements
  4\tFailed to fetch URL
  5\tFailed to parse statements
  6\tFailed to encode JSON

Examples:
  gron /tmp/apiresponse.json
  gron http://jsonplaceholder.typicode.com/users/1 
  curl -s http://jsonplaceholder.typicode.com/users/1 | gron
  gron http://jsonplaceholder.typicode.com/users/1 | grep company | gron --ungron
"""

KEYWORDS = set('break case catch class const continue debugger default delete do else export extends false finally for function if import in instanceof new null return super switch this throw true try typeof var void while with yield'.split())

class Number:
    __slots__ = ('raw',)
    def __init__(self, raw): self.raw = str(raw)
    def __repr__(self): return self.raw

MISSING = object()

def ordered_pairs(pairs):
    d = OrderedDict()
    for k, v in pairs:
        if k in d:
            del d[k]
        d[k] = v
    return d

DECODER = json.JSONDecoder(object_pairs_hook=ordered_pairs,
                           parse_int=Number, parse_float=Number,
                           parse_constant=lambda s: (_ for _ in ()).throw(ValueError('invalid constant')))

def replace_surrogates(s):
    # Go's JSON decoder replaces unpaired surrogates with U+FFFD.
    return ''.join(('\ufffd' if 0xD800 <= ord(ch) <= 0xDFFF else ch) for ch in s)

def normalize(v):
    if isinstance(v, str):
        return replace_surrogates(v)
    if isinstance(v, list):
        return [normalize(x) for x in v]
    if isinstance(v, OrderedDict):
        out = OrderedDict()
        for k, val in v.items():
            out[replace_surrogates(k)] = normalize(val)
        return out
    if isinstance(v, dict):
        return OrderedDict((replace_surrogates(str(k)), normalize(val)) for k, val in v.items())
    return v

def go_json_error(e, text):
    # json.Decoder returns a handful of distinctive messages.  Reproduce common ones.
    if text.strip() == '':
        return 'EOF'
    msg = getattr(e, 'msg', str(e))
    if isinstance(e, json.JSONDecodeError):
        if msg == 'Unterminated string starting at':
            return 'unexpected EOF'
        if msg == 'Expecting value':
            ch = text[e.pos:e.pos+1]
            if ch:
                return "invalid character %r looking for beginning of value" % ch
            return 'EOF'
        if msg == 'Expecting property name enclosed in double quotes':
            ch = text[e.pos:e.pos+1]
            if ch:
                return "invalid character %r looking for beginning of object key string" % ch
        if msg == "Expecting ':' delimiter":
            ch = text[e.pos:e.pos+1]
            if ch:
                return "invalid character %r after object key" % ch
        if msg == "Expecting ',' delimiter":
            ch = text[e.pos:e.pos+1]
            if ch:
                return "invalid character %r after object key:value pair" % ch
    return str(e)

def loads_one(text):
    idx = 0
    n = len(text)
    while idx < n and text[idx] in ' \t\r\n':
        idx += 1
    if idx >= n:
        raise EOFError('EOF')
    val, end = DECODER.raw_decode(text, idx)
    return normalize(val)

def is_id_start(ch):
    if ch in '$_': return True
    cat = unicodedata.category(ch)
    return cat.startswith('L') or cat == 'Nl'

def is_id_continue(ch):
    if ch in '$_': return True
    cat = unicodedata.category(ch)
    return cat.startswith('L') or cat.startswith('N') or cat.startswith('M') or cat in ('Pc',)

def is_identifier(s):
    if not s or s in KEYWORDS: return False
    if not is_id_start(s[0]): return False
    return all(is_id_continue(ch) for ch in s[1:])

def quote_string(s):
    s = replace_surrogates(s)
    out = ['"']
    for ch in s:
        o = ord(ch)
        if ch == '"': out.append('\\"')
        elif ch == '\\': out.append('\\\\')
        elif ch == '\b': out.append('\\b')
        elif ch == '\f': out.append('\\f')
        elif ch == '\n': out.append('\\n')
        elif ch == '\r': out.append('\\r')
        elif ch == '\t': out.append('\\t')
        elif o < 0x20: out.append('\\u%04x' % o)
        elif o == 0x2028: out.append('\\u2028')
        elif o == 0x2029: out.append('\\u2029')
        else: out.append(ch)
    out.append('"')
    return ''.join(out)

def encode_compact(v):
    if isinstance(v, Number): return v.raw
    if v is None: return 'null'
    if v is True: return 'true'
    if v is False: return 'false'
    if isinstance(v, str): return quote_string(v)
    if isinstance(v, list): return '[' + ','.join(encode_compact(x) for x in v) + ']'
    if isinstance(v, (dict, OrderedDict)):
        return '{' + ','.join(quote_string(str(k)) + ':' + encode_compact(v[k]) for k in v.keys()) + '}'
    if isinstance(v, int): return str(v)
    if isinstance(v, float): return repr(v).lower()
    return quote_string(str(v))

def encode_pretty(v, indent=0):
    sp = ' ' * indent
    if isinstance(v, (dict, OrderedDict)):
        keys = sorted(v.keys(), key=lambda x: str(x))
        if not keys: return '{}'
        parts = ['{']
        for i, k in enumerate(keys):
            comma = ',' if i < len(keys)-1 else ''
            parts.append(' '*(indent+2) + quote_string(str(k)) + ': ' + encode_pretty(v[k], indent+2) + comma)
        parts.append(sp + '}')
        return '\n'.join(parts)
    if isinstance(v, list):
        if not v: return '[]'
        parts = ['[']
        for i, item in enumerate(v):
            comma = ',' if i < len(v)-1 else ''
            parts.append(' '*(indent+2) + encode_pretty(item, indent+2) + comma)
        parts.append(sp + ']')
        return '\n'.join(parts)
    return encode_compact(v)

def value_for_container(v):
    if isinstance(v, (dict, OrderedDict)): return OrderedDict()
    if isinstance(v, list): return []
    return v

def walk(v, path, out):
    out.append((list(path), value_for_container(v)))
    if isinstance(v, (dict, OrderedDict)):
        for k, val in v.items():
            walk(val, path + [k], out)
    elif isinstance(v, list):
        for i, val in enumerate(v):
            walk(val, path + [i], out)

def component_prefix(c):
    if isinstance(c, int):
        return ('[', 0, c)
    if is_identifier(c):
        return ('.', c)
    return ('[', 1, quote_string(c))

def sort_key(stmt):
    path = stmt[0]
    return tuple(component_prefix(c) for c in path)

def format_path(path, color=False):
    if not color:
        s = 'json'
        for c in path:
            if isinstance(c, int): s += '[' + str(c) + ']'
            else:
                if is_identifier(c): s += '.' + c
                else: s += '[' + quote_string(c) + ']'
        return s
    blue='\033[34;1m'; resetb='\033[0;22m'; mag='\033[35m'; reset='\033[0m'; yellow='\033[33m'; red='\033[31m'
    s = blue + 'json' + resetb
    for c in path:
        if isinstance(c, int):
            s += mag+'['+reset + red+str(c)+reset + mag+']'+reset
        else:
            if is_identifier(c): s += '.' + blue + c + resetb
            else: s += mag+'['+reset + yellow+quote_string(c)+reset + mag+']'+reset
    return s

def color_value(v):
    red='\033[31m'; yellow='\033[33m'; cyan='\033[36m'; mag='\033[35m'; reset='\033[0m'
    txt = encode_compact(v)
    if isinstance(v, str): return yellow + txt + reset
    if isinstance(v, Number) or isinstance(v, (int,float)): return red + txt + reset
    if v is None or v is True or v is False: return cyan + txt + reset
    if isinstance(v, (list, dict, OrderedDict)): return mag + txt + reset
    return txt

def emit_statements(data, opts):
    stmts = []
    walk(data, [], stmts)
    if not opts.get('no_sort'):
        stmts.sort(key=sort_key)
    lines = []
    if opts.get('json_mode'):
        for p, v in stmts:
            lines.append(encode_compact([p, v]))
    else:
        color = opts.get('color')
        for p, v in stmts:
            if color:
                lines.append(format_path(p, True) + ' = ' + color_value(v) + ';')
            else:
                lines.append(format_path(p, False) + ' = ' + encode_compact(v) + ';')
    return '\n'.join(lines) + ('\n' if lines else '')

def read_input(source, opts):
    if source is None or source == '-':
        try:
            return sys.stdin.buffer.read().decode('utf-8', 'replace'), 0
        except Exception as e:
            print(str(e), file=sys.stderr); return None, 2
    if source.startswith('http://') or source.startswith('https://'):
        try:
            handlers = []
            # Proxy flags are accepted for CLI compatibility; urllib honors environment by default.
            ctx = None
            if opts.get('insecure') and source.startswith('https://'):
                ctx = ssl._create_unverified_context()
            req = urllib.request.Request(source, headers={'User-Agent':'gron/dev'})
            with urllib.request.urlopen(req, context=ctx, timeout=30) as r:
                return r.read().decode('utf-8', 'replace'), 0
        except Exception as e:
            print('Get "%s": %s' % (source, getattr(e, 'reason', e)), file=sys.stderr)
            return None, 4
    try:
        with open(source, 'rb') as f:
            return f.read().decode('utf-8', 'replace'), 0
    except OSError as e:
        print('open %s: %s' % (source, e.strerror), file=sys.stderr)
        return None, 1

def form_json(text, opts):
    if opts.get('stream'):
        arr = []
        err = None
        for line in text.splitlines():
            try:
                arr.append(loads_one(line))
            except EOFError as e:
                err = str(e); break
            except Exception as e:
                err = go_json_error(e, line); break
        sys.stdout.write(emit_statements(arr, opts))
        if err is not None:
            print('failed to form statements: ' + err, file=sys.stderr)
            return 3
        return 0
    try:
        data = loads_one(text)
    except EOFError as e:
        print('failed to form statements: ' + str(e), file=sys.stderr); return 3
    except Exception as e:
        print('failed to form statements: ' + go_json_error(e, text), file=sys.stderr); return 3
    try:
        sys.stdout.write(emit_statements(data, opts))
        return 0
    except Exception as e:
        print('failed to encode JSON: ' + str(e), file=sys.stderr); return 6

def scan_statement(line):
    in_str = False; esc = False
    for i, ch in enumerate(line):
        if in_str:
            if esc: esc = False
            elif ch == '\\': esc = True
            elif ch == '"': in_str = False
        else:
            if ch == '"': in_str = True
            elif ch == ';': return line[:i]
    return None

def parse_ident_at(s, i):
    if i >= len(s) or not is_id_start(s[i]): return None, i
    j = i + 1
    while j < len(s) and is_id_continue(s[j]): j += 1
    return s[i:j], j

def parse_path(path):
    i = 0
    first, i2 = parse_ident_at(path, i)
    if first is None: return None
    comps = [] if first == 'json' else [first]
    i = i2
    while i < len(path):
        ch = path[i]
        if ch == '.':
            i += 1
            ident, j = parse_ident_at(path, i)
            if ident is None: return None
            comps.append(ident); i = j
        elif ch == '[':
            i += 1
            if i < len(path) and path[i] == '"':
                # find matching JSON string quote
                start = i; i += 1; esc = False
                while i < len(path):
                    c = path[i]
                    if esc: esc = False
                    elif c == '\\': esc = True
                    elif c == '"':
                        i += 1; break
                    i += 1
                else: return None
                lit = path[start:i]
                try:
                    key = loads_one(lit)
                except Exception:
                    return None
                if not isinstance(key, str): return None
                if i >= len(path) or path[i] != ']': return None
                comps.append(key); i += 1
            else:
                start = i
                while i < len(path) and path[i].isdigit(): i += 1
                if start == i: return None
                if i >= len(path) or path[i] != ']': return None
                comps.append(int(path[start:i] or '0')); i += 1
        else:
            return None
    return comps

def parse_value(vs):
    vs = vs.strip()
    if vs == '{}': return OrderedDict()
    if vs == '[]': return []
    try:
        val = loads_one(vs)
    except Exception:
        return MISSING
    # The statement grammar produced by gron only uses primitives plus empty containers.
    if isinstance(val, (dict, OrderedDict, list)):
        if isinstance(val, (dict, OrderedDict)) and len(val)==0: return OrderedDict()
        if isinstance(val, list) and len(val)==0: return []
        return MISSING
    return val

def statement_from_line(line):
    stmt = scan_statement(line)
    if stmt is None:
        return None, 'statement has no value', line
    if '=' not in stmt:
        return None, 'invalid statement', stmt.strip().split(' ')[0] if stmt.strip() else ''
    path_s, val_s = stmt.split('=', 1)
    path_s = path_s.strip(); val_s = val_s.strip()
    path = parse_path(path_s)
    if path is None:
        return None, 'invalid statement', path_s if path_s.endswith('.') else (path_s.split()[0] if path_s else '')
    val = parse_value(val_s)
    if val is MISSING:
        return None, 'invalid value `%s`' % val_s, stmt.strip()
    return (path, val), None, None

def ensure_container(parent, key, want_list):
    newc = [] if want_list else OrderedDict()
    if isinstance(parent, list):
        while len(parent) <= key: parent.append(None)
        cur = parent[key]
        if want_list:
            if not isinstance(cur, list): parent[key] = newc
        else:
            if not isinstance(cur, (dict, OrderedDict)): parent[key] = newc
        return parent[key]
    else:
        cur = parent.get(key, MISSING)
        if want_list:
            if not isinstance(cur, list): parent[key] = newc
        else:
            if not isinstance(cur, (dict, OrderedDict)): parent[key] = newc
        return parent[key]

def assign_path(root, path, value):
    def empty_container(x): return (isinstance(x, list) and len(x)==0) or (isinstance(x, (dict, OrderedDict)) and len(x)==0)
    if not path:
        if root is not MISSING and empty_container(value):
            if (isinstance(root, list) and isinstance(value, list)) or (isinstance(root, (dict, OrderedDict)) and isinstance(value, (dict, OrderedDict))):
                return root
        return value
