    if isinstance(path[0], int):
        if not isinstance(root, list): root = []
    else:
        if not isinstance(root, (dict, OrderedDict)): root = OrderedDict()
    cur = root
    for idx, comp in enumerate(path[:-1]):
        nxt = path[idx+1]
        want_list = isinstance(nxt, int)
        if isinstance(cur, list):
            if not isinstance(comp, int):
                # impossible mixed path for arrays; replace with object-like not supported
                return root
            cur = ensure_container(cur, comp, want_list)
        else:
            cur = ensure_container(cur, comp, want_list)
    last = path[-1]
    if isinstance(cur, list):
        if not isinstance(last, int): return root
        while len(cur) <= last: cur.append(None)
        old = cur[last]
        if empty_container(value) and ((isinstance(old, list) and isinstance(value, list)) or (isinstance(old, (dict, OrderedDict)) and isinstance(value, (dict, OrderedDict)))):
            return root
        cur[last] = value
    else:
        old = cur.get(last, MISSING)
        if old is not MISSING and empty_container(value) and ((isinstance(old, list) and isinstance(value, list)) or (isinstance(old, (dict, OrderedDict)) and isinstance(value, (dict, OrderedDict)))):
            return root
        cur[last] = value
    return root

def ungron_text(text):
    root = MISSING; parsed = 0
    for rawline in text.splitlines():
        line = rawline.rstrip('\r')
        if line == '':
            continue
        if line[0].isspace():
            continue
        item, err, ctx = statement_from_line(line)
        if err:
            print('ungron failed for `%s`: %s' % (ctx, err), file=sys.stderr)
            return 5
        path, val = item
        root = assign_path(root, path, val)
        parsed += 1
    if parsed == 0:
        print('no statements were parsed', file=sys.stderr)
        return 5
    sys.stdout.write(encode_pretty(root) + '\n')
    return 0

def ungron_json_stream(text):
    root = MISSING; parsed = 0
    for rawline in text.splitlines():
        line = rawline.rstrip('\r')
        if line == '': continue
        try:
            pair = loads_one(line)
            if not isinstance(pair, list) or len(pair) != 2 or not isinstance(pair[0], list):
                raise ValueError('invalid statement')
            path = []
            for c in pair[0]:
                if isinstance(c, Number): path.append(int(c.raw))
                elif isinstance(c, int): path.append(c)
                elif isinstance(c, str): path.append(c)
                else: raise ValueError('invalid path')
            root = assign_path(root, path, pair[1]); parsed += 1
        except Exception as e:
            print('ungron failed for `%s`: invalid statement' % line, file=sys.stderr)
            return 5
    if parsed == 0:
        print('no statements were parsed', file=sys.stderr); return 5
    sys.stdout.write(encode_pretty(root) + '\n')
    return 0

def values_mode(text):
    outs = []
    for rawline in text.splitlines():
        line = rawline.rstrip('\r')
        if not line or line[0].isspace(): continue
        stmt = scan_statement(line)
        if stmt is None or '=' not in stmt: continue
        val_s = stmt.split('=',1)[1].strip()
        val = parse_value(val_s)
        if val is MISSING or isinstance(val, (list, dict, OrderedDict)): continue
        if isinstance(val, str): outs.append(val)
        else: outs.append(encode_compact(val))
    if outs:
        sys.stdout.write('\n'.join(outs) + '\n')
    return 0

def parse_args(argv):
    opts = dict(ungron=False, values=False, color=False, monochrome=False, stream=False, insecure=False, json_mode=False, no_sort=False, proxy=None, noproxy=None)
    args=[]; i=0
    while i < len(argv):
        a=argv[i]
        if a == '--':
            args.extend(argv[i+1:]); break
        if not a.startswith('-') or a == '-':
            args.extend(argv[i:]); break
        if a in ('-h','--help'):
            sys.stderr.write(USAGE); raise SystemExit(0)
        if a == '--version':
            print('gron version dev'); raise SystemExit(0)
        if a in ('-u','--ungron'): opts['ungron']=True
        elif a in ('-v','--values'): opts['values']=True
        elif a in ('-c','--colorize'): opts['color']=True
        elif a in ('-m','--monochrome'): opts['monochrome']=True
        elif a in ('-s','--stream'): opts['stream']=True
        elif a in ('-k','--insecure'): opts['insecure']=True
        elif a in ('-j','--json'): opts['json_mode']=True
        elif a == '--no-sort': opts['no_sort']=True
        elif a in ('-x','--proxy'):
            if i+1 >= len(argv):
                print('flag needs an argument: ' + ('-x' if a=='-x' else '-proxy'), file=sys.stderr); sys.stderr.write(USAGE); raise SystemExit(2)
            opts['proxy']=argv[i+1]; i += 1
        elif a.startswith('--proxy='):
            opts['proxy']=a.split('=',1)[1]
        elif a == '--noproxy':
            if i+1 >= len(argv):
                print('flag needs an argument: -noproxy', file=sys.stderr); sys.stderr.write(USAGE); raise SystemExit(2)
            opts['noproxy']=argv[i+1]; i += 1
        elif a.startswith('--noproxy='):
            opts['noproxy']=a.split('=',1)[1]
        else:
            name = a
            if name.startswith('--'): name = '-' + name[2:]
            print('flag provided but not defined: ' + name, file=sys.stderr); sys.stderr.write(USAGE); raise SystemExit(2)
        i += 1
    if opts['monochrome']:
        opts['color'] = False
    elif not opts['color']:
        opts['color'] = sys.stdout.isatty()
    return opts, args

def main(argv):
    try:
        opts, args = parse_args(argv)
    except SystemExit as e:
        return int(e.code)
    source = args[0] if args else None
    text, code = read_input(source, opts)
    if code != 0: return code
    if opts.get('values') and not opts.get('ungron'):
        return values_mode(text)
    if opts.get('ungron'):
        if opts.get('json_mode'):
            return ungron_json_stream(text)
        return ungron_text(text)
    return form_json(text, opts)

if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
